int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    cin >> H >> W;
    vector<string> grid(H);
    for (int i = 0; i < H; i++) {
        cin >> grid[i];
    }

    // For each column, number of 'I' below each row
    vector<vector<int>> ingotBelow(H + 1, vector<int>(W, 0));
    for (int j = 0; j < W; j++) {
        for (int i = H - 1; i >= 0; i--) {
            ingotBelow[i][j] = ingotBelow[i + 1][j] + (grid[i][j] == 'I');
        }
    }

    // For each row, number of 'O' to the right of each column
    vector<vector<int>> orbRight(H, vector<int>(W + 1, 0));
    for (int i = 0; i < H; i++) {
        for (int j = W - 1; j >= 0; j--) {
            orbRight[i][j] = orbRight[i][j + 1] + (grid[i][j] == 'O');
        }
    }

    long long power = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == 'J') {
                power += (long long)orbRight[i][j + 1] * ingotBelow[i + 1][j];
            }
        }
    }

    cout << power << "\n";
    return 0;
}

