int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    cin >> H >> W;
    vector<string> S(H);
    for (int i = 0; i < H; ++i) cin >> S[i];

    // rightO[i][j] = number of 'O' in row i, strictly to the right of column j
    vector<vector<int>> rightO(H, vector<int>(W, 0));
    for (int i = 0; i < H; ++i) {
        int cnt = 0;
        for (int j = W - 1; j >= 0; --j) {
            rightO[i][j] = cnt;
            if (S[i][j] == 'O') cnt++;
        }
    }

    // downI[i][j] = number of 'I' in column j, strictly below row i
    vector<vector<int>> downI(H, vector<int>(W, 0));
    for (int j = 0; j < W; ++j) {
        int cnt = 0;
        for (int i = H - 1; i >= 0; --i) {
            downI[i][j] = cnt;
            if (S[i][j] == 'I') cnt++;
        }
    }

    long long ans = 0;
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (S[i][j] == 'J') {
                ans += 1LL * rightO[i][j] * downI[i][j];
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

#include <stdio.h>

int main() {
    int H, W;
    scanf("%d %d", &H, &W);
    char grid[H][W+1];
    for (int i = 0; i < H; i++) {
        scanf("%s", grid[i]);
    }

    // Count J's per row and O's per column
    int rowJ[H], colO[W];
    for (int i = 0; i < H; i++) rowJ[i] = 0;
    for (int j = 0; j < W; j++) colO[j] = 0;

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == 'J') rowJ[i]++;
            if (grid[i][j] == 'O') colO[j]++;
        }
    }

    long long power = 0;
    // For each cell with an Ingot, count valid (J, O) pairs
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == 'I') {
                // J in same row i, O in same column j
                power += (long long)rowJ[i] * colO[j];
            }
        }
    }

    printf("%lld\n", power);
    return 0;
}

