int main(void) {
    int H, W;
    if (scanf("%d %d", &H, &W) != 2) return 0;

    char *grid = (char *)malloc((size_t)H * (W + 1));
    long long *downI = (long long *)calloc((size_t)H * W, sizeof(long long));
    if (!grid || !downI) return 0;

    for (int i = 0; i < H; i++) {
        scanf("%s", grid + (size_t)i * (W + 1));
    }

    /* downI[i][j] = number of 'I' in column j below row i */
    for (int j = 0; j < W; j++) {
        long long cnt = 0;
        for (int i = H - 1; i >= 0; i--) {
            downI[(size_t)i * W + j] = cnt;
            if (grid[(size_t)i * (W + 1) + j] == 'I') cnt++;
        }
    }

    long long ans = 0;

    for (int i = 0; i < H; i++) {
        long long rightO = 0;
        /* Count O to the right while scanning from right to left */
        for (int j = W - 1; j >= 0; j--) {
            char c = grid[(size_t)i * (W + 1) + j];
            if (c == 'J') {
                ans += rightO * downI[(size_t)i * W + j];
            }
            if (c == 'O') rightO++;
        }
    }

    printf("%lld\n", ans);

    free(grid);
    free(downI);
    return 0;
}

import sys

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    H = int(input_data[idx]); idx += 1
    W = int(input_data[idx]); idx += 1

    grid = []
    for i in range(H):
        grid.append(input_data[idx]); idx += 1

    # Precompute O_row[i] = number of 'O' in row i
    O_row = [0] * H
    for i in range(H):
        for c in grid[i]:
            if c == 'O':
                O_row[i] += 1

    # Precompute I_col[j] = number of 'I' in column j
    I_col = [0] * W
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'I':
                I_col[j] += 1

    # Sum over all jewels
    ans = 0
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'J':
                ans += I_col[j] * O_row[i]

    print(ans)

