import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int H = fs.nextInt();
        int W = fs.nextInt();

        char[][] grid = new char[H][];
        for (int i = 0; i < H; i++) {
            grid[i] = fs.next().toCharArray();
        }

        // rightO[i][j] = number of 'O' cells to the right of (i, j) in the same row
        long[][] rightO = new long[H][W];
        for (int i = 0; i < H; i++) {
            long cnt = 0;
            for (int j = W - 1; j >= 0; j--) {
                rightO[i][j] = cnt;
                if (grid[i][j] == 'O') cnt++;
            }
        }

        // downI[i][j] = number of 'I' cells below (i, j) in the same column
        long[][] downI = new long[H][W];
        for (int j = 0; j < W; j++) {
            long cnt = 0;
            for (int i = H - 1; i >= 0; i--) {
                downI[i][j] = cnt;
                if (grid[i][j] == 'I') cnt++;
            }
        }

        long ans = 0;
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (grid[i][j] == 'J') {
                    ans += rightO[i][j] * downI[i][j];
                }
            }
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
